begin;
create extension if not exists pgtap with schema extensions;
select plan(10);
delete from public.team_members;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001301','vat.test@example.test');
insert into public.team_members(id,auth_user_id,email,display_name) values('00000000-0000-4000-8000-000000001301','00000000-0000-4000-8000-000000001301','vat.test@example.test','Equipo IVA');
insert into public.team_member_roles(member_id,role) values('00000000-0000-4000-8000-000000001301','designer'),('00000000-0000-4000-8000-000000001301','billing');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000001301';
select public.save_customer('00000000-0000-4000-8000-000000001310',null,'{"display_name":"Cliente IVA"}');
select public.create_direct_order('00000000-0000-4000-8000-000000001320','00000000-0000-4000-8000-000000001310',null,null,'','[{"description":"Con IVA","client_description":"Con IVA","specifications":"","quantity":5,"amount":"100.50","with_vat":true},{"description":"Sin IVA","client_description":"Sin IVA","specifications":"","quantity":5,"amount":"50","with_vat":false}]','{"amount":"160","paid_on":"1901-01-15","method":"cash"}');
select is((select vat_amount from public.order_items where order_id='00000000-0000-4000-8000-000000001320' and with_vat),21.11::numeric,'Redondeo de IVA por línea');
select is((public.order_money('00000000-0000-4000-8000-000000001320')->>'balance')::numeric,11.61::numeric,'Seña y saldo usan total con IVA');
select lives_ok($$select public.edit_order('00000000-0000-4000-8000-000000001320',1,'[{"description":"Corregido","client_description":"Corregido","specifications":"","quantity":5,"amount":"120","with_vat":true},{"description":"Sin IVA","client_description":"Sin IVA","specifications":"","quantity":5,"amount":"50","with_vat":false}]','','{}','')$$,'Edición recalcula IVA');
select is((public.order_money('00000000-0000-4000-8000-000000001320')->>'balance')::numeric,35.20::numeric,'Saldo recalculado al editar');
select is((public.billing_order('00000000-0000-4000-8000-000000001320')->>'total')::numeric,145.20::numeric,'Facturación toma solo el total marcado');
select public.mark_order_invoiced('00000000-0000-4000-8000-000000001320');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000001320',2,'[{"description":"Corregido","client_description":"Corregido","specifications":"","quantity":5,"amount":"120","with_vat":true},{"description":"Sin IVA","client_description":"Sin IVA","specifications":"","quantity":5,"amount":"50","with_vat":false}]','','{}','')$$,'23514',null,'No cambia importes de ítems ya facturados');
select public.save_quote('00000000-0000-4000-8000-000000001330',null,'','','','[{"description":"Con IVA","client_description":"Con IVA","specifications":"","quantity":5,"amount":"100.50","with_vat":true},{"description":"Sin IVA","client_description":"Sin IVA","specifications":"","quantity":5,"amount":"50","with_vat":false}]','00000000-0000-4000-8000-000000001310');
select public.approve_quote('00000000-0000-4000-8000-000000001330',1,'');
select lives_ok($$select public.create_order_from_quote('00000000-0000-4000-8000-000000001330',2,null,null,null,'{"amount":"160","paid_on":"1901-01-15","method":"cash"}',null,'','{}',array[true,false])$$,'Convierte presupuesto y acepta seña sobre el total con IVA');
select is((select total from public.orders where quote_id='00000000-0000-4000-8000-000000001330'),171.61::numeric,'Nota generada suma IVA por ítem');
select is((select count(*) from public.order_items where order_id=(select id from public.orders where quote_id='00000000-0000-4000-8000-000000001330') and with_vat),1::bigint,'Solo se marca el ítem seleccionado');
select is((public.order_money((select id from public.orders where quote_id='00000000-0000-4000-8000-000000001330'))->>'deposit')::numeric,160::numeric,'Seña se guarda una sola vez');
reset role;
select * from finish();
rollback;
